    { name = 'About this data', group = 'Server', desc = 'What was collected for Olympus XI, when, and what is missing. Source: https://github.com/bobertdrake/olympus-xi-patch/releases/tag/wiki ; https://olympus-games.dev', steps = { { title = 'What was fetched', note = '• Olympus Wiki data pack (the /owiki data) v20261022.2209, built 2026-10-22, from GitHub release "wiki" of bobertdrake/olympus-xi-patch via the REST API; sha256 verified.\n• Pack counts: 7344 monsters, 7330 items, 3310 recipes, 203 zones, 6213 NPCs, 20 lore, 455 quests, 170 missions, 136 guides.\n• Site pages from the olympus-games.dev sitemap: /, /ballista, /community, /create, /fallen, /fishing, /join, /news (plus astraea, lantern, nanaa, vaudun), /rules.\n• Fetched 2026-10-28.' }, { title = 'What these files hold', note = '• Gear: 4094 items (custom 79, craft 2938, vendor 603, drop 229, quest 159, NM 645, chest 22, Dynamis 224).\n• Skills: crafting bands from 3310 recipes plus merchant and guild shop prices.\n• Quests: 455 quests and 170 missions; 82 flagged impl=npc and labelled not fully scripted.\n• Server notes: website statements, each checked against the fetched page.' }, { title = 'Not covered', note = '• No combat/magic skill caps or fishing skill levels.\n• No Ballista or Angler\'s Mark exchange stock, and no numeric EXP/drop multipliers.\n• No level, slot or jobs for Olympus-only NM gear.\n• Leaderboards, Hall of the Fallen and live player data deliberately omitted.\n• robots-disallowed paths (/api/, /download, GitHub release downloads) not requested; release read via api.github.com.' }, { title = 'Licence', note = '• No licence stated; GitHub reports none.\n• Olympus XI and its wiki belong to Olympus Games; this is a pointer for players, not a copy.\n• Fan-run project, not affiliated with Square Enix; runs on LandSandBoat.' } } },
    { name = 'Rates and progression', group = 'Server', desc = 'Olympus XI era, level cap and the one-time character mode choice. Source: https://olympus-games.dev ; https://olympus-games.dev/news ; https://olympus-games.dev/fallen', steps = { { title = 'Era and level cap', note = '• Level 75 era, content through Treasures of Aht Urhgan.\n• Some later quality-of-life changes are included.' }, { title = 'Character modes (chosen once, no going back)', note = '• Picked once, just after a new character first arrives; it cannot be changed.\n• Normal: standard play with everyone; deaths are recoverable.\n• Titan Mode: 5x EXP, better finds, faster recovery and a golden laurel by your name; dying to a monster resets that job to level 1 and is announced server-wide.\n• Hardcore: no boosts (era EXP, base crafting and fishing skill-ups); party, trade and mail only with Hardcore players; no Auction House; dying to a monster deletes the character permanently.\n• Titan Mode was called Hardcore until Oct 11, 2026.' } } },
    { name = 'Gear and drops', group = 'Server', desc = 'Olympus-only notorious monsters, their zones, and where to check drop data. Source: https://olympus-games.dev/news ; https://olympus-games.dev ; https://github.com/bobertdrake/olympus-xi-patch/releases/tag/wiki', steps = { { title = 'Olympus XI notorious monsters', note = '• 64 NMs across 16 leveling zones, 4 per zone (e.g. La Theine Plateau, Konschtat Highlands, Castle Oztroja, Eldieme Necropolis).\n• Each drops unique gear for one role; bring a full party.\n• Some have time windows, some need specific weather, some must be summoned.\n• Astraea The Measure: Ru\'Aun Gardens; alliance required.\n• Vaudun The Unspoken (a Bastokan warmage): Pashhow Marshlands; ignores passers-by, responds when you cast near him.\n• Nanaa Fuego: sings on the sand in Valkurm Dunes.\n• Kings and dragons are back with ToAU-era spawn and claim rules.' }, { title = 'Drop rates', note = '• /owiki shows this server\'s own drop rates and data for monsters, items, recipes, zones, quests and missions.' }, { title = 'Story monsters in the Olympus Wiki', note = '• Astraea The Measure (The Last Arbiter of Tu\'Lia): Ru\'Aun Gardens\n• Vaudun The Unspoken (The Warmage Who Never Finished His Spell): Pashhow Marshlands\n• Nanaa Fuego (The Bard of the Valkurm Mirage): Valkurm Dunes\n• The Drowned Lantern (A Light Beneath the Selbina Pier)\n• Strange Company on La Theine, La Theine Plateau: Bellwether Barnabus, Gnashgut Hrakkor, Unblinking Wyatt, Witchring Wendeline\n• Sand and Thorn in Tahrongi, Tahrongi Canyon: Centurion Lucanus, Twiceborn Tilly, Waxen Matriarch, Zo\'Pha Hollowreed\n• The Long Wind of Konschtat, Konschtat Highlands: Gnarlmaw the Wayward, Stormkettle, Sunbask Sorrel, Ze\'Dha Grumblestone\n• Old Ground at Batallia, Batallia Downs: Gravesteel Alard, Gutrip the Striped, Mockingwing, Moonreaper\n• Under the Shells of Beadeaux, Beadeaux: Bilegrist, Mu\'Gha the Hexmender, Ra\'Gho Shellwarden, The Gloomtongue\n• Behind Oztroja\'s Brass Doors, Castle Oztroja: Huu Pazza the Augur, Moo Shakka the Executioner, The Ember Herald, Zii Gekka the Gambler\n• Inside the Walls of Davoi, Davoi: Beastrider Zurgat, Bonebreaker Grukmak, Gloomchant Hukrok, Gunnhild the Hired\n• What Qufim\'s Ice Keeps, Qufim Island: Gnawl of the White Water, Hailtusk, Rimeshell Rygor, Thrymgrind Frostjaw\n• The Thorns of Rolanberry, Rolanberry Fields: Bramblesap Bunta, Captain Pazzlix, Lady Verdigris, Silkmother Vashka\n• The Long Grass of Sauromugue, Sauromugue Champaign: Grassveil Balamor, Rii Haqi the Featherbolt, Siktat Ja the Rainmaker, The Lamplighter\n• What Yhoator Remembers, Yhoator Jungle: Gremlin King Mukk, Grudge-laden Maraberry, The Mawbloom, The Rotroot Elder\n• The Hoards of Sea Serpent Grotto, Sea Serpent Grotto: Gaal the Shellsplitter, Kuur the Reefwarden, Mirebrine, Plii the Conchblower\n• The Turnings of Onzozo, Labyrinth of Onzozo: Fizzbang the Gadgeteer, Goldscale, Stoneglare, The Caravan Qutrub\n• What Feeds in the Crawlers\' Nest, Crawlers\' Nest: Pitmaw, Rumbleback, Sapsweet, Stingtail Kharu\n• The Sealed Halls of Garlaige, Garlaige Citadel: Banneret Aldric, Old Chimneystack, The Bellows, The Gatewarden\n• The Restless of Eldieme, The Eldieme Necropolis: Shade of Sir Ambrosine, Sister Ombrine, The Bowman of Eldieme, The Hollow Thinker' } } },
    { name = 'Crafting and gathering', group = 'Server', desc = 'Crafting notes and the weekly Selbina fishing tournament on Olympus XI. Source: https://olympus-games.dev/news ; https://olympus-games.dev ; https://olympus-games.dev/news/lantern', steps = { { title = 'Crafting', note = '• Hardcore characters get base crafting and fishing skill-up rates.\n• Launcher addons include a crafting book and a fishing HUD.' }, { title = 'Selbina Fishing Tournament', note = '• Saturdays, 9 AM Pacific, on the Selbina pier, run by the Fishermen\'s Guild.\n• Get certified by Chenon, then fish for one hour in your own division.\n• Each weighed fish earns Angler\'s Marks, exchanged with the guild for bait, rods and equipment.\n• Best five fish per division win a title and a guild prize.\n• On busy mornings, watch the water beneath the pier.' } } },
    { name = 'Quests and missions', group = 'Server', desc = 'What quest and mission walkthrough data Olympus XI provides. Source: https://olympus-games.dev/news ; https://github.com/bobertdrake/olympus-xi-patch/releases/tag/wiki', steps = { { title = 'Walkthroughs', note = '• Walkthroughs cover nation, Zilart and Chains of Promathia missions plus job unlock quests; steps check off automatically as you progress.\n• The data refreshes each time you press Play.' }, { title = 'In the Olympus Wiki pack', note = '• 455 quests, 170 missions, 136 walkthroughs.\n• 82 quests are impl=npc (NPCs exist, quest not fully scripted); the rest are impl=full.' } } },
    { name = 'Combat and PvP', group = 'Server', desc = 'Ballista PvP and finding groups on Olympus XI. Source: https://olympus-games.dev ; https://olympus-games.dev/news', steps = { { title = 'Ballista', note = '• Queue with the Pursuivant in Ru\'Lude Gardens; a match begins once both sides have players.\n• Every match awards points; the exchange offers leveling gear for all jobs, plus spells and titles.\n• Top performers earn unique gear.' }, { title = 'Groups', note = '• Works for full linkshells or small groups.\n• Find a party with /oparty (Party Finder) or on the Discord.' } } },
    { name = 'Travel and quality of life', group = 'Server', desc = 'Installing Olympus XI and the launcher\'s built-in addons. Source: https://olympus-games.dev ; https://olympus-games.dev/join ; https://olympus-games.dev/news', steps = { { title = 'Getting started', note = '• Talk to your Mog House Moogle on arrival for starter items.\n• Free Windows launcher installs the official client (~7.7 GB download; ~22 GB free space needed during install).\n• The PlayOnline updater is not required.' }, { title = 'Launcher and addons', note = '• Map and minimap with shareable pins and routes.\n• Party Finder linked to the launcher and Discord.\n• Enmity meters and a skillchain helper.\n• Controller support; R1 opens the Olympus menu.\n• HD textures and labelled HD maps preinstalled; maps show only this server\'s Home Points.\n• Addons that reveal hidden monsters or skip travel are banned.\n• VanaCore, a new client by Vekien of CatsEyeXI, is in early-access beta; Ashita remains default and you can switch back.' } } },
    { name = 'Commands', group = 'Server', desc = 'In-game and Discord commands on Olympus XI. Source: https://olympus-games.dev/news ; https://olympus-games.dev', steps = { { title = 'In game', note = '• /owiki: look up monsters, items, recipes, zones, quests and missions.\n• /oparty: Party Finder.\n• /oui: customize the Olympus UI.\n• /ofriend (needs updated launcher): friends online, their location and activity.\n• /vana: VanaCore beta client options.\n• Controller R1: Olympus menu.' }, { title = 'Discord', note = '• /beastiary play in the Olympus Discord.\n• /link connects your character so the cards can find you.' } } },
    { name = 'Rules', group = 'Server', desc = 'Olympus XI conduct rules for the game and Discord. Source: https://olympus-games.dev/rules', steps = { { title = 'Server rules (in game and on Discord)', note = '• No real-money trading of gil, items, characters, accounts or services, including offers.\n• Report bugs or exploits privately to a mod; do not share how they work.\n• No harassment, personal attacks, slurs or hate speech.\n• No ads or invites for other servers, Discords, shops or services without mod approval.\n• Penalties: warning, timeout or ban.' } } },
